/* Archive action links */
.archive-pill-btn {
  border: none;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: bold;
  cursor: pointer;
}
.archive-pill-btn.sell { background-color: #e8f8f5; color: #2ecc71; border: 1px solid #2ecc71; }
.archive-pill-btn.die { background-color: #fceeee; color: #e74c3c; border: 1px solid #e74c3c; }

/* Dynamic badge background for archived entries */
.tag-archivedsold, .tag-archiveddied { background-color: #7f8c8d; }
